// Example of --extra steps for e2e_browser.cjs: exercises a module generated by add_module.py (kind "clients").
//   node scripts/e2e_browser.cjs --app . --extra scripts/extra_example.cjs
// The default flow ends on the login screen (hard reload), so unlock first. Copy and adapt for your own modules.
module.exports = async ({ page, step, shot }) => {
  await page.fill('input[autocomplete="current-password"]', "Correct123");
  await page.locator('button[type="submit"]').click();
  await page.waitForSelector("aside nav");
  await step("module: sidebar entry, dashboard card and empty state", async () => {
    await page.locator('aside a[href*="/clients"]').click();
    await page.waitForURL(/\/clients/);
    await page.waitForSelector("text=/لا توجد عناصر|Nothing here yet|Rien ici/");
  });
  await step("module: add a client (text, phone, secret, decimal comma, select) and see it in the table", async () => {
    await page.getByRole("button", { name: /إضافة عميل|Add client|Ajouter : client/ }).click();
    const dlg = page.locator('[role="dialog"]');
    await dlg.locator("input").nth(0).fill("Ali Benali");
    await dlg.locator('input[type="tel"]').fill("0550123456");
    await dlg.locator('input[autocomplete="off"]').fill("portal-secret-1");
    await dlg.locator('input[inputmode="decimal"]').fill("1500,5");
    await dlg.locator("select").selectOption("paused");
    await shot("module-dialog");
    await dlg.getByRole("button", { name: /حفظ|Save|Enregistrer/ }).click();
    await page.waitForSelector("td:has-text('Ali Benali')");
    await page.waitForSelector("td:has-text('1500.5')");
    await shot("module-list");
  });
  await step("module data is encrypted at rest and counted on the dashboard", async () => {
    const dump = await page.evaluate(() => JSON.stringify(Object.fromEntries(Object.entries(localStorage))));
    if (/Ali Benali|portal-secret-1/.test(dump)) throw new Error("plaintext in localStorage");
    await page.locator('aside a[href*="/dashboard"]').click();
    await page.waitForSelector("b:has-text('Ali Benali')"); // recent-activity entry
    await page.waitForSelector('a[href*="/clients"] .num:text-is("1")'); // the counter card
  });
};
